use std::process::Command;
use std::io::{self, Write};

/// Execute a system command and return the output
/// 
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Vector of arguments for the command
/// 
/// # Returns
/// * `Ok(String)` - The stdout output of the command
/// * `Err(String)` - Error message if command execution failed
pub fn execute_command(command: &str, args: Vec<&str>) -> Result<String, String> {
    let output = Command::new(command)
        .args(&args)
        .output();

    match output {
        Ok(output) => {
            if output.status.success() {
                let stdout = String::from_utf8_lossy(&output.stdout);
                Ok(stdout.to_string())
            } else {
                let stderr = String::from_utf8_lossy(&output.stderr);
                Err(format!("Command failed with exit code {:?}: {}", output.status.code(), stderr))
            }
        }
        Err(e) => Err(format!("Failed to execute command: {}", e)),
    }
}

/// Execute a shell command through the system shell
/// 
/// # Arguments
/// * `command` - The shell command to execute
/// 
/// # Returns
/// * `Ok(String)` - The stdout output of the command
/// * `Err(String)` - Error message if command execution failed
#[cfg(unix)]
pub fn execute_shell_command(command: &str) -> Result<String, String> {
    execute_command("sh", vec!["-c", command])
}

#[cfg(windows)]
pub fn execute_shell_command(command: &str) -> Result<String, String> {
    execute_command("cmd", vec!["/C", command])
}

/// Sanitize a command to prevent injection attacks
/// 
/// # Arguments
/// * `input` - The input string to sanitize
/// 
/// # Returns
/// * `String` - The sanitized string
pub fn sanitize_input(input: &str) -> String {
    // Remove potentially dangerous characters
    input.replace([';', '&', '|', '`', '$', '(', ')'], "")
}

